import * as T from './vendor/three.module.js';
import {ballProperties,dragK} from './ball-properties.js';
export const INCH=.0254,G=9.80665,WHEEL=.096/INCH,BALL=2.8,MAX_RPM=6000;
// Intake and shooter face the robot front (-local Z); rear-mounted shooter fires forward; rear edge rests at the fence.
export const SHOT_POSE={x:-12.75,z:-72+8.055,theta:Math.PI};
export const frontHeading=(dx,dz)=>Math.atan2(-dx,-dz);
export const fencePose=alliance=>Number(alliance)===0?{...SHOT_POSE}:{x:-SHOT_POSE.x,z:-SHOT_POSE.z,theta:SHOT_POSE.theta+Math.PI};
export const REAR_EDGE=8.055,REAR_BALL_GAP=3.6,SHOOTER_REAR_OFFSET=REAR_EDGE-REAR_BALL_GAP-WHEEL/2,HOOD_START=-100.5*Math.PI/180,HOOD_SWEEP=124*Math.PI/180;
// Side section after the clockwise quarter-turn: rear is left, forward is right.
export const guidePoint=(theta,radius)=>({u:-radius*Math.cos(theta),y:radius*Math.sin(theta)});
export const outline=[[-10,0],[-10,10],[0,14],[10,10],[10,0]];
export function launcher(angle,height=6,compression=.15,pose=SHOT_POSE,diameter=BALL){const a=angle*Math.PI/180,r=WHEEL/2+diameter/2-compression/2,guideExit=Math.PI/2-a,forward=new T.Vector3(-Math.sin(pose.theta),0,-Math.cos(pose.theta)),center=new T.Vector3(pose.x,height,pose.z).addScaledVector(forward,-SHOOTER_REAR_OFFSET),release=guidePoint(guideExit,r),origin=center.clone().addScaledVector(forward,release.u);origin.y+=release.y;return {a,guideExit,hoodStart:HOOD_START,hoodSweep:guideExit-HOOD_START,r,diameter,forward,hoodRadius:WHEEL/2+diameter-compression,center,origin};}
export function makeTarget(cell){cell.updateWorldMatrix(true,false);const matrix=cell.matrixWorld.clone(),inverse=matrix.clone().invert(),triangles=[];for(let i=0;i<5;i++){const [x,y]=outline[i],[u,v]=outline[(i+1)%5];const a=new T.Vector3(x,y,-6),b=new T.Vector3(u,v,-6),c=new T.Vector3(u,v,6),d=new T.Vector3(x,y,6);triangles.push(new T.Triangle(a,b,c),new T.Triangle(a,c,d));}for(let i=1;i<4;i++)triangles.push(new T.Triangle(new T.Vector3(...outline[0],-6),new T.Vector3(...outline[i],-6),new T.Vector3(...outline[i+1],-6)));return {matrix,inverse,triangles,center:new T.Vector3(0,7,6).applyMatrix4(matrix),normal:new T.Vector3(0,0,1).transformDirection(matrix)};}
export function pointAt(s,t){const index=Math.min(s.samples.length-2,Math.max(0,Math.floor(t/s.dt))),a=s.samples[index],b=s.samples[index+1],f=Math.max(0,Math.min(1,(t-a.t)/(b.t-a.t||1)));return a.p.clone().lerp(b.p,f);}
function integrate(settings){const type=settings.type??(settings.diameter===3.6?'nectar':'pollen'),props=ballProperties(type),l=launcher(settings.angle,settings.height,settings.compression,settings.pose,props.diameter),rpm=settings.power*MAX_RPM,surface=Math.PI*.096*rpm/60,speed=surface*settings.transfer,v=speed/INCH,vy=v*Math.sin(l.a),vx=v*Math.cos(l.a)*l.forward.x,vz=v*Math.cos(l.a)*l.forward.z,dt=1/480,k=dragK(type),samples=[{t:0,p:l.origin.clone(),vy:vy*INCH}];let x=l.origin.x*INCH,y=l.origin.y*INCH,z=l.origin.z*INCH,ux=vx*INCH,uy=vy*INCH,uz=vz*INCH,apexHeight=l.origin.y,apexTime=0;const floor=props.diameter/2*INCH;
for(let i=1;i<=4800;i++){const magnitude=Math.hypot(ux,uy,uz),factor=k*magnitude;ux-=factor*ux*dt;uy+=(-G-factor*uy)*dt;uz-=factor*uz*dt;x+=ux*dt;y+=uy*dt;z+=uz*dt;const p=new T.Vector3(x/INCH,y/INCH,z/INCH);samples.push({t:i*dt,p,vy:uy});if(p.y>apexHeight){apexHeight=p.y;apexTime=i*dt;}if(y<=floor)break;}
const last=samples.at(-1),duration=last.t;return {...l,type,mass:props.mass,rpm,surface,speed,vx,vy,vz,dt,samples,duration,apexTime,apexHeight,range:last.p.clone().sub(l.origin).dot(l.forward),status:'miss',message:'Misses the raised opening',entry:null,impact:null};}
export function simulate(settings,target,checkPanels=true){const shot=integrate(settings);if(settings.power===0){shot.status='off';shot.message='Motor off';return shot;}const n=target.normal,r=shot.diameter/2;let lastDistance=shot.origin.clone().sub(target.center).dot(n);
for(let i=1;i<shot.samples.length;i++){const b=shot.samples[i],a=shot.samples[i-1],distance=b.p.clone().sub(target.center).dot(n);if(lastDistance>0&&distance<=0){const f=lastDistance/(lastDistance-distance),p=a.p.clone().lerp(b.p,f),local=p.clone().applyMatrix4(target.inverse);let margin=Infinity;for(let j=0;j<5;j++){const [x,y]=outline[j],[u,v]=outline[(j+1)%5],dx=u-x,dy=v-y;margin=Math.min(margin,(dy*(local.x-x)-dx*(local.y-y))/Math.hypot(dx,dy));}const verticalSpeed=a.vy+(b.vy-a.vy)*f;shot.entry={t:a.t+(b.t-a.t)*f,point:p,local,margin,descending:verticalSpeed<0,verticalSpeed};if(margin>=r+.26){shot.status=verticalSpeed<0?'entry':'rising';shot.message=verticalSpeed<0?'Descending entry predicted':'Reaches opening while rising';}else shot.message=margin>0?'Clips the opening rim':'Misses the raised opening';break;}lastDistance=distance;}
if(checkPanels){const end=shot.entry?.t??shot.duration,near=new T.Vector3();for(const sample of shot.samples){if(sample.t>end)break;const q=sample.p.clone().applyMatrix4(target.inverse);if(Math.abs(q.x)>12||q.y< -2||q.y>16||Math.abs(q.z)>8)continue;for(const triangle of target.triangles){triangle.closestPointToPoint(q,near);if(q.distanceTo(near)<r+.20){shot.impact={t:sample.t,point:sample.p};shot.status='blocked';shot.message='Hits the hive before entering';break;}}if(shot.impact)break;}}
return shot;}
export function findArc(settings,target){let best=null;for(let angle=65;angle<=88;angle+=.5){let low=0,high=1;const probe=integrate({...settings,angle,power:1}),d=target.center.clone().sub(probe.origin).dot(probe.forward);if(d<=0)continue;const lateral=target.center.clone().sub(probe.origin).addScaledVector(probe.forward,-d);if(Math.hypot(lateral.x,lateral.z)>6)continue;
for(let j=0;j<14;j++){const power=(low+high)/2,shot=integrate({...settings,angle,power});let height=0;for(let i=1;i<shot.samples.length;i++){const a=shot.samples[i-1].p,b=shot.samples[i].p,da=a.clone().sub(shot.origin).dot(shot.forward),db=b.clone().sub(shot.origin).dot(shot.forward);if(db>=d){height=a.y+(b.y-a.y)*(d-da)/(db-da||1);break;}}if(height<target.center.y)low=power;else high=power;}
const power=(low+high)/2,result=simulate({...settings,angle,power},target);if(result.status==='entry'&&(!best||power<best.power))best={angle,power,result};}return best;}
